import{_ as a,o as r,c as e,a6 as i}from"./chunks/framework.BlDtR6jM.js";const o="/Art_web_public/assets/rigitright_3rded-1.CUEwpDle.jpg",l="/Art_web_public/assets/image.FohlfjLO.png",n="/Art_web_public/assets/image-1.BNGaLoIt.png",s="/Art_web_public/assets/image-2.CobVkjkQ.png",p="/Art_web_public/assets/image-3.CTXtinOn.png",h="/Art_web_public/assets/image-4.CDI3578h.png",d="/Art_web_public/assets/image-5.CRAm6LVC.png",c="/Art_web_public/assets/image-6.DcoJXWMc.png",q=JSON.parse('{"title":"RIG IT RIGHT!","description":"","frontmatter":{"readingTime":"14 min read"},"headers":[],"relativePath":"全流程美术/绑定/RIG_IT_RIGHT/RIG_IT_RIGHT.md","filePath":"全流程美术/绑定/RIG_IT_RIGHT/RIG_IT_RIGHT.md"}'),_={name:"全流程美术/绑定/RIG_IT_RIGHT/RIG_IT_RIGHT.md"};function b(u,t,g,m,T,I){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="rig-it-right" tabindex="-1">RIG IT RIGHT! <a class="header-anchor" href="#rig-it-right" aria-label="Permalink to &quot;RIG IT RIGHT!&quot;">​</a></h1><p>MAYA ANIMATION RIGGING CONCEPTS THIRD <img src="'+o+'" alt="alt text"></p><h2 id="节点-node" tabindex="-1">节点 Node <a class="header-anchor" href="#节点-node" aria-label="Permalink to &quot;节点 Node&quot;">​</a></h2><p>每个对象一开始都有两个节点。你可以把节点看作一个包含信息并对该信息进行处理的盒子。<br> 一个对象有两个节点：变换节点和形状节点。<br> 查看形状节点主要有两种方式。默认情况下，在你刚开始使用Maya时，只处理变换节点。对于普通用户来说，形状节点通常是隐藏的，因为它们会造成干扰。这就好比开车时一直把引擎盖打开，是不可取的。</p><h2 id="属性、枢轴点和层级结构" tabindex="-1">属性、枢轴点和层级结构 <a class="header-anchor" href="#属性、枢轴点和层级结构" aria-label="Permalink to &quot;属性、枢轴点和层级结构&quot;">​</a></h2><h3 id="zeroing-out" tabindex="-1">Zeroing Out <a class="header-anchor" href="#zeroing-out" aria-label="Permalink to &quot;Zeroing Out&quot;">​</a></h3><p>而当你冻结变换时，实际上只是在进行矩阵乘法运算，让艺术家觉得数值已经被清零了。事实上，在Creative Crash上有一些脚本可以帮你恢复那些本不该冻结时却被冻结的数值。<br> 在Maya 2022及以上版本中，你会看到一个额外的区域，标题为“偏移父矩阵”。这是个很巧妙的功能，我们之后会深入了解。<br><img src="'+l+'" alt="alt text"><br> 冻结变换只是假装将平移和旋转属性设为零。这些数值其实还在，只是对动画师隐藏起来了而已。</p><h3 id="使用组节点保存动画" tabindex="-1">使用组节点保存动画 <a class="header-anchor" href="#使用组节点保存动画" aria-label="Permalink to &quot;使用组节点保存动画&quot;">​</a></h3><p>在大纲视图中，我们可以看到组节点是奖杯节点的父节点。如果你选择组节点并查看通道盒，会发现缺少了一些东西——没有形状节点。组节点仅仅是包含平移、旋转和缩放信息的变换节点。它们没有任何可见的内容，因此在通道盒中没有任何输入项。由于它们只是空的变换节点，所以非常适合动画师用作可动画节点。</p><p>如果它从一边倾倒然后再倒向另一边呢？在这种情况下，你会使用多个枢轴点或多个组节点来进行动画制作。这种方法是3D动画的基石，自其诞生以来就从未改变过。对于道具（非角色对象）而言，通常枢轴点动画就足够了。</p><p>要制作具有多个枢轴点的奖杯，只需为每个枢轴点添加一个组即可。使用组节点进行动画制作时，层级结构非常重要。如果你有两个组节点，分别是Trophy_Tip_Left（奖杯左侧尖端）和Trophy_Tip_Right（奖杯右侧尖端），那么父节点会影响子节点。因此，如果你旋转左侧的组节点且它是父节点，右侧的组节点会随之移动。但如果你旋转右侧的组节点，左侧的组节点会保持原位，因为它是父节点。<br><img src="'+n+'" alt="alt text"><br> 要确保父节点是第一个需要设置动画的枢轴点。所以在我们新的故事板中，奖杯先向左旋转，再向右旋转，然后稳定下来，最后在其底座上轻微旋转。为此，我们将添加三个组节点。</p><h3 id="锁定不需要动画的部分" tabindex="-1">锁定不需要动画的部分 <a class="header-anchor" href="#锁定不需要动画的部分" aria-label="Permalink to &quot;锁定不需要动画的部分&quot;">​</a></h3><p>这一点非常重要。当你制作完一个绑定并将其交给一个完全不清楚你所做工作的人时，你与他们沟通的主要方式是：只给他们需要的东西。你的任务是锁定所有你不希望被设置动画的属性。</p><p>恢复隐藏属性<br><img src="'+s+'" alt="alt text"></p><p>组节点的顺序会极大地影响控制器的表现。<br><img src="'+p+'" alt="alt text"></p><h2 id="变形器-deformers" tabindex="-1">变形器 DEFORMERS <a class="header-anchor" href="#变形器-deformers" aria-label="Permalink to &quot;变形器 DEFORMERS&quot;">​</a></h2><h3 id="簇-cluster" tabindex="-1">簇 Cluster <a class="header-anchor" href="#簇-cluster" aria-label="Permalink to &quot;簇 Cluster&quot;">​</a></h3><p>勾选簇的相对属性，簇才会跟随物体移动<br><img src="'+h+'" alt="alt text"></p><p>绑定装置是复杂的存在，有许多活动部件。如果你刚开始接触某件事，就试图一下子做太多，那么你将无法很好地理解哪里出了问题以及为什么会出问题。最好的做法是将绑定装置的功能分解成小块；先在测试对象上让它工作起来，这样你就能完全理解它；然后再慢慢地把各个部分组合起来。</p><p>当你变得更熟练时，一些常规的东西你可以直接绑定而不需要测试，之后你想在绑定中加入的所有其他复杂功能，都需要以一种简化、专注的方式花费一些研究和开发时间。这是最好的解决问题的方法：把它分解成可管理的部分，然后一个一个地攻克它们。</p><p>高级绑定师会将自己的操作编写成脚本，这样他们只需调整所做的操作，然后重新运行脚本即可。</p><p>现在，我让这看起来很简单，就像我的几何老师一样，他给我讲证明的时候总是条理清晰。但是，一旦下课，只剩下我的笔记时，我几乎无法重现我们在课堂上做过的任何内容，直到我用自己的问题反复练习之后才可以。这里也是一样：抛开这一章，自己重新做这个绑定，把每一步的逻辑理清楚，直到明白为止。不要试图通过一步步跟着做来进行绑定。那样会把它变成一个只能做出一种结果的配方。</p><p><img src="'+d+'" alt="alt text"><br> 布线的合理性</p><h2 id="用户控制器-user-controllers" tabindex="-1">用户控制器 USER CONTROLLERS <a class="header-anchor" href="#用户控制器-user-controllers" aria-label="Permalink to &quot;用户控制器 USER CONTROLLERS&quot;">​</a></h2><p>要找到这些属性很麻烦。任何头脑清醒的动画师都不想花时间点击所有节点来制作动画。这是我们过去的做法，是20世纪90年代的绑定风格。所有动画师都必须知道大纲视图是什么。想象一下，在1996年迪士尼早期的3D动画长片中，有一个会说话、会走动的恐龙（不过它们不会唱歌）。一个大型角色的大纲视图里有成百上千个层级很深的节点。动画师必须能够在这些节点中穿梭，找到需要制作动画的部分。这速度慢得离谱。后来有人想出了一个主意：在恐龙上方放一个图标，让动画师可以抓取并进行动画制作。他们创建了屏幕控制。他们在恐龙上方放置了圆锥体，当你抓住圆锥体并旋转时，恐龙的脖子或尾巴就会跟着旋转。在当时，这是一项惊人的进步。当动画师不再负责为自己的角色进行绑定时，这就变得很有必要了，而且很多时候他们也不知道如何进行绑定。不管动画师是否懂得绑定，动画控制都节省了大量时间。</p><h3 id="父约束-parent-constraint-和-点约束-定向约束-point-orient-的关键差别" tabindex="-1">父约束（Parent Constraint）和 点约束 + 定向约束（Point + Orient）的关键差别 <a class="header-anchor" href="#父约束-parent-constraint-和-点约束-定向约束-point-orient-的关键差别" aria-label="Permalink to &quot;父约束（Parent Constraint）和 点约束 + 定向约束（Point + Orient）的关键差别&quot;">​</a></h3><p>关键区别——<strong>旋转基准轴（枢轴点）的归属不同</strong>，这会直接影响绑定的旋转逻辑，尤其对控制器操作的准确性至关重要。</p><p>结合Maya绑定实操和书中的绑定逻辑，用通俗的语言拆解如下：</p><h3 id="一、核心区别-旋转基准轴-枢轴点-是谁的" tabindex="-1">一、核心区别：旋转基准轴（枢轴点）是谁的？ <a class="header-anchor" href="#一、核心区别-旋转基准轴-枢轴点-是谁的" aria-label="Permalink to &quot;一、核心区别：旋转基准轴（枢轴点）是谁的？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约束类型</th><th>旋转基准轴（枢轴点）</th><th>本质逻辑</th></tr></thead><tbody><tr><td>父约束（Parent Constraint）</td><td>驱动对象（Driver）的枢轴点</td><td>被驱动对象“跟随驱动对象的枢轴点”旋转/移动——相当于把被驱动对象“挂”在驱动对象的枢轴点上，驱动对象绕自己的枢轴转，被驱动对象也跟着转。</td></tr><tr><td>点约束+定向约束（Point + Orient）</td><td>被驱动对象（Driven）的枢轴点</td><td>被驱动对象“在自己的枢轴点上”响应驱动对象的运动——位置跟着驱动对象动（点约束），旋转姿态跟着驱动对象变（定向约束），但旋转的中心始终是自己的枢轴点。</td></tr></tbody></table><h3 id="二、实操影响-为什么这很重要-结合书中案例" tabindex="-1">二、实操影响：为什么这很重要？（结合书中案例） <a class="header-anchor" href="#二、实操影响-为什么这很重要-结合书中案例" aria-label="Permalink to &quot;二、实操影响：为什么这很重要？（结合书中案例）&quot;">​</a></h3><p>书中反复强调“枢轴点位置决定绑定合理性”（如道具绑定的枢轴点、关节绑定的旋转中心），这个差异会直接导致“旋转是否符合预期”：</p><h4 id="场景1-书本-盒子开合绑定-铰链式旋转" tabindex="-1">场景1：书本“盒子开合绑定”（铰链式旋转） <a class="header-anchor" href="#场景1-书本-盒子开合绑定-铰链式旋转" aria-label="Permalink to &quot;场景1：书本“盒子开合绑定”（铰链式旋转）&quot;">​</a></h4><p>假设你要做一个可开合的盒子：</p><ul><li><p>被驱动对象：盒子的盖子（Lid_GEO），其枢轴点已正确放在“铰链处”（盒子边缘，确保盖子绕铰链转）；</p></li><li><p>驱动对象：控制器（Lid_CNTRL），为了方便动画师选择，控制器放在盖子外侧（其枢轴点在控制器自身中心，而非盒子铰链）。</p></li><li><p>若用 <strong>父约束（Parent Constraint）</strong>： 旋转控制器时，盖子会绕“控制器的枢轴点”（外侧）旋转——结果是盖子会向外甩动，而不是绕铰链开合，完全不符合预期（这就是书中说的“rotate will happen incorrectly”）。</p></li><li><p>若用 <strong>点约束+定向约束</strong>： 点约束：盖子的位置跟着控制器动（确保控制器能带动盖子）； 定向约束：盖子的旋转姿态跟着控制器变，但旋转中心是“盖子自身的枢轴点（铰链）”——旋转控制器时，盖子会绕铰链开合，完全符合设计逻辑。<br><img src="'+c+'" alt="alt text"></p></li></ul><h4 id="场景2-书本-关节控制器绑定-如颈部关节驱动" tabindex="-1">场景2：书本“关节控制器绑定”（如颈部关节驱动） <a class="header-anchor" href="#场景2-书本-关节控制器绑定-如颈部关节驱动" aria-label="Permalink to &quot;场景2：书本“关节控制器绑定”（如颈部关节驱动）&quot;">​</a></h4><ul><li><p>被驱动对象：颈部关节（Neck_JNT），枢轴点在关节中心（旋转基准）；</p></li><li><p>驱动对象：头部控制器（Head_CNTRL），为了操作方便，控制器在头部外侧（枢轴点在控制器中心）。</p></li><li><p>若用 <strong>父约束</strong>： 旋转控制器时，颈部关节会绕“控制器的枢轴点”（外侧）旋转——导致颈部骨骼错位、蒙皮扭曲，绑定失效。</p></li><li><p>若用 <strong>点约束+定向约束</strong>： 颈部关节绕自己的枢轴点旋转，同时位置和姿态跟随控制器——既保证了关节旋转的正确性，又让动画师能在外侧方便地操作控制器。</p></li></ul><h3 id="三、书本隐含的核心原则" tabindex="-1">三、书本隐含的核心原则 <a class="header-anchor" href="#三、书本隐含的核心原则" aria-label="Permalink to &quot;三、书本隐含的核心原则&quot;">​</a></h3><p>作者强调这个差异，本质是在传递绑定的关键逻辑：</p><ol><li><strong>“旋转中心必须在正确的位置”</strong>：无论是盒子铰链、关节中心，旋转的基准轴（枢轴点）必须与对象的运动逻辑一致（这是书中“Happy Math”和“关节位置/定向”规则的延伸）；</li><li><strong>控制器的“操作位置”与“旋转基准”可以分离</strong>：动画师需要的是“容易点击的控制器位置”，而对象需要的是“正确的旋转基准轴”——点约束+定向约束实现了这种分离，而父约束会强制两者绑定到同一枢轴点，灵活性不足；</li><li><strong>父约束的适用场景</strong>：只有当“驱动对象的枢轴点”与“被驱动对象的旋转基准轴”完全重合时，父约束才适用（如主控制器驱动整个角色的根节点，两者枢轴点都在世界中心）。</li></ol>',40)])])}const f=a(_,[["render",b]]);export{q as __pageData,f as default};
